def front_and_rear(s):
    """The program dawnr proved in `t`, written in Python (checked against `t`, not itself proved).

    requires len(s) >= 2
    ensures  len(r) == 2
    ensures  r[0] == s[0]
    ensures  r[1] == s[len(s) - 1]

    Outside its `requires` it raises ValueError: nothing was proved there.
    """
    if not (_t_ints(s, 1)):
        raise TypeError('front_and_rear: `s` must be a list of integers; nothing was proved for anything else')
    s = _t_tuple(s)
    if not _t_requires(s):
        raise ValueError('front_and_rear: this input is outside what was proved (requires len(s) >= 2)')
    _t_result = _t_core(s)
    return _t_shape(_t_result, ('tuple',))

def _t_core(s):
    r = (s[0], s[(len(s) - 1)], )
    return r

def _t_requires(s):
    try:
        return bool((len(s) >= 2))
    except (IndexError, ZeroDivisionError):   # a `requires` with no value here admits nothing
        return False

def _t_tuple(v):
    return tuple(_t_tuple(x) for x in v) if isinstance(v, (list, tuple)) else v

def _t_ints(v, depth):
    if depth == 0:
        return isinstance(v, int) and not isinstance(v, bool)
    return isinstance(v, (list, tuple)) and all(_t_ints(x, depth - 1) for x in v)

def _t_shape(v, kinds):
    if not isinstance(v, tuple):
        return v
    inner = [_t_shape(x, kinds[1:] or kinds[-1:]) for x in v]
    return tuple(inner) if kinds[0] == "tuple" else inner
